 const readers:CurrentSession[]=[];for(let n=0;n<5;n++)readers.push(await withPartnerDatabase(async db=>{const principalId=randomUUID(),membershipId=randomUUID(),sessionId=randomUUID(),token=randomBytes(32).toString("base64url"),loginName="synthetic-benchmark-reader-"+principalId;await db.query("INSERT INTO principals(id,login_name,display_name) VALUES($1,$2,'Synthetic Benchmark Reader')",[principalId,loginName]);await db.query("INSERT INTO memberships(id,principal_id,workspace_id,kind,role) VALUES($1,$2,$3,'internal','member')",[membershipId,principalId,DEMO_IDS.workspace]);await db.query("INSERT INTO login_sessions(id,principal_id,token_hash,expires_at) VALUES($1,$2,$3,clock_timestamp()+interval '3 hours')",[sessionId,principalId,hashSessionToken(token)]);return {principalId,membershipId,sessionId,token,loginName,workspaceId:DEMO_IDS.workspace,displayName:"Synthetic Benchmark Reader",kind:"internal",role:"member",expiresAt:new Date(Date.now()+10800000)} as CurrentSession;}));
 const support=[];for(let n=0;n<180;n++){await setupWindow();support.push(await partnerAcceptedEvidence(actors.author,actors.reviewer,DEMO_IDS.sharedCustomer,`Synthetic original dependency ${n}`));}
 const sources:PartnerSource[]=[];for(let n=0;n<20;n++){await setupWindow();sources.push((await partnerAcceptedEvidence(actors.author,actors.reviewer,DEMO_IDS.sharedCustomer,`Synthetic selected benchmark evidence ${n}`,{evidenceRevisionIds:support.slice(n*9,n*9+9).map(s=>s.revisionId)})).reference);}
