 const verification=[],checkpointWrites=[];for(let n=50;n<100;n++){
  const assigned=await assign(n,partners[1]),guide=guides[n],body={attempted:"Synthetic benchmark independently demonstrated practice",result:"Synthetic separately accepted observed result",blockers:[],observedAt:new Date(Date.now()-1000).toISOString(),sources:[sources[0]]};await setupWindow();const draft=await writePartnerCheckpoint(partners[1],{...partnerCommandEnvelope(),action:"checkpoint.save",assignmentId:assigned.targetId!,checkpointId:guide.content.checkpoints[0].id,expectedVersion:1,content:body}),attempt=(await readPartnerAssignment(partners[1],assigned.targetId!)).checkpoints[0].attempts[0],submitted=await writePartnerCheckpoint(partners[1],{...partnerCommandEnvelope(),action:"checkpoint.submit",assignmentId:assigned.targetId!,checkpointId:guide.content.checkpoints[0].id,attemptId:attempt.attemptId,revisionId:attempt.revisionId,contentDigest:attempt.contentDigest,expectedVersion:draft.version!});verification.push({assignmentId:assigned.targetId!,checkpointId:guide.content.checkpoints[0].id,attemptId:attempt.attemptId,revisionId:attempt.revisionId,contentDigest:attempt.contentDigest,version:submitted.version!});const writing=await assign(n,partners[2]);checkpointWrites.push({assignmentId:writing.targetId!,checkpointId:guide.content.checkpoints[0].id,version:1,body});
 }
 const publications=[];for(let n=0;n<50;n++){await setupWindow();const guide=guides[n],saved=await writePartnerGuide(actors.author,{...partnerCommandEnvelope(),action:"guide.revise",guideId:guide.guideId,expectedVersion:3,acceptedRevisionId:guide.acceptedRevisionId,baselineId:guide.baselineId,content:{...guide.content,title:guide.content.title.slice(0,180)+" reviewed revision"}}),current=await readPartnerGuide(actors.author,guide.guideId),submitted=await writePartnerGuide(actors.author,{...partnerCommandEnvelope(),action:"guide.submit",guideId:guide.guideId,revisionId:current.revisionId,contentDigest:current.contentDigest,expectedVersion:saved.version!});publications.push({guideId:guide.guideId,revisionId:current.revisionId,contentDigest:current.contentDigest,version:submitted.version!});}
 await setupWindow();await withPartnerDatabase(db=>db.query("UPDATE login_sessions SET expires_at=clock_timestamp()+interval '3 hours' WHERE id=ANY($1::uuid[])",[[...partners,...readers,actors.reviewer,actors.author].map(a=>a.sessionId)]));return {actors,customers,partners,readers,sources,guides,maximumAssignment,verification,checkpointWrites,publications,dataset:{customers:120,organizations:2,individuallyGrantedMembers:10,acceptedEngagements:120,guides:120,maximumLessons:20,maximumCheckpoints:40,maximumOriginalClosure:200,activeAssignmentsForMemberCustomer:100}};
